"use client";
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams, useRouter } from 'next/navigation';
import Sidebar from "../../../components/sidebar"; // Importation de Sidebar
import Navbar from "../../../components/Navbar";
import { HiArrowNarrowLeft } from "react-icons/hi";

export default function Edituser() {
  const [inputs, setInputs] = useState({
    nom: "",
    prenom: "",
    email: "",
    motDePasse: "",
    annee: "",
  });
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const { id } = useParams();
  const router = useRouter();

  useEffect(() => {
    if (id) {
      getUser();
    } else {
      setError("L'identifiant de l'encadrant est manquant");
      setIsLoading(false);
    }
  }, [id]);

  function getUser() {
    axios.get(`http://localhost:5000/api/getEncadrant/${id}`)
      .then(function(response) {
        const userData = response.data; // Utilisez response.data directement
        setInputs({
          nom: userData.nom,
          prenom: userData.prenom,
          email: userData.email,
          motDePasse: userData.motDePasse,
          annee: userData.annee,
        });
        setIsLoading(false);
      })
      .catch(err => {
        console.error("Erreur lors de la récupération de l'encadrant:", err);
        setError("Erreur lors de la récupération des données de l'encadrant.");
        setIsLoading(false);
      });
  }

  const handleChange = (event) => {
    const { name, value } = event.target;
    setInputs(prevValues => ({ ...prevValues, [name]: value }));
  }

  const handleSubmit = (event) => {
    event.preventDefault();
    axios.put(`http://localhost:5000/api/editEncadrant/${id}`, inputs)
      .then(function(response) {
        router.push('/users/readEnca'); // Redirige vers la page d'accueil après la mise à jour
      })
      .catch(err => {
        console.error("Erreur lors de la mise à jour de l'encadrant:", err);
        setError("Erreur lors de la mise à jour de l'encadrant.");
      });
  }

  if (isLoading) {
    return <div>Loading...</div>;
  }

  return (
    <div className="flex h-screen w-screen">
      {/* Sidebar */}
      <Sidebar className="h-screen" />
      <div className="w-full flex flex-col h-screen">
        {/* Navbar */}
        <Navbar />
        <div className="w-full flex-1 py-5 flex flex-col items-center overflow-hidden">
          <div className="max-w-md mx-auto mt-5">
          <button
  onClick={() => router.push("/users/readEnca")}
  className="mb-5 flex items-center text-blue-600 hover:text-blue-800 transition font-medium text-lg"
>
  <HiArrowNarrowLeft className="mr-2 text-2xl" /> 
</button>

            <h1 className="text-2xl text-center mb-2">Modifier Encadrant</h1>
            {error && <p className="text-red-500 text-center">{error}</p>}
            <form onSubmit={handleSubmit}>
              <div className="mb-5">
                <label htmlFor="nom" className="block text-sm font-medium text-gray-900">Nom</label>
                <input
                  type="text"
                  name="nom"
                  id="nom"
                  value={inputs.nom || ''}
                  className="w-full px-4 py-2 mt-2 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm transition"
                  placeholder="Nom..."
                  onChange={handleChange}
                />
              </div>
              <div className="mb-5">
                <label htmlFor="prenom" className="block text-sm font-medium text-gray-900">Prénom</label>
                <input
                  type="text"
                  name="prenom"
                  id="prenom"
                  value={inputs.prenom || ''}
                  className="w-full px-4 py-2 mt-2 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm transition"
                  placeholder="Prénom..."
                  onChange={handleChange}
                />
              </div>
              <div className="mb-5">
                <label htmlFor="email" className="block text-sm font-medium text-gray-900">Email</label>
                <input
                  type="email"
                  name="email"
                  id="email"
                  value={inputs.email || ''}
                  className="w-full px-4 py-2 mt-2 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm transition"
                  placeholder="Email..."
                  onChange={handleChange}
                />
              </div>
              <div className="mb-5">
                <label htmlFor="motDePasse" className="block text-sm font-medium text-gray-900">Mot de passe</label>
                <input
                  type="password"
                  name="motDePasse"
                  id="motDePasse"
                  value={inputs.motDePasse || ''}
                  className="w-full px-4 py-2 mt-2 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm transition"
                  placeholder="Mot de passe..."
                  onChange={handleChange}
                />
              </div>
              <div className="mb-5">
  <label htmlFor="annee" className="block text-sm font-medium text-gray-900">Année</label>
  <select
    name="annee"
    id="annee"
    value={inputs.annee || ''}
    className="w-full px-4 py-2 mt-2 border border-blue-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none shadow-sm transition"
    onChange={handleChange}
  >
    <option value="" disabled>Annee</option>
    {Array.from({ length: 20 }, (_, i) => {
      const year = new Date().getFullYear() - i;
      return (
        <option key={year} value={year}>
          {year}
        </option>
      );
    })}
  </select>
</div>

              <button
                type="submit"
                className="bg-blue-500 text-white w-full py-2 px-5 rounded-lg shadow-md hover:bg-blue-600"
              >
                Modifier
              </button>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
}